import tarfile
import os

def extract_file(tar_path, extract_dir):
    tar = tarfile.open(tar_path)

    tar.extractall(path=extract_dir)

    tar.close()

    for f in os.listdir():
        if not os.path.isfile(f):
            continue

        os.chmod(f, 0o777)

def main():
    extract_dir = '/home/user/tmp/'
    tar_path = os.path.join(extract_dir, 'files.tar.gz')

    extract_file(tar_path, extract_dir)

if __name__ == '__main__':
    main()
